import { currentStep } from './session-execution.js';
import { executionElapsedMs,formatDuration,restRemainingSeconds } from './session-timer.js';
function e(v){return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');}
function groupName(type){return ({biserie:'Biserie',triserie:'Triserie',circuito:'Circuito',amrap:'AMRAP',tabata:'Tabata'})[type]||type;}
function syncBanner(execution){
  const status=execution?.syncStatus||'clean';if(status==='clean')return '';
  if(status==='pending')return '<div class="m26-sync-banner is-pending" role="status">Guardado en este dispositivo · pendiente de sincronización.</div>';
  if(status==='conflict')return `<div class="m26-sync-banner is-conflict" role="alert">Existe una versión más reciente en el servidor. Tu progreso local está protegido y requiere revisión.</div>`;
  return `<div class="m26-sync-banner is-rejected" role="alert">No fue posible confirmar el último cambio. El progreso local se conserva.</div>`;
}
function timerStrip(execution){const elapsed=formatDuration(executionElapsedMs(execution));const rest=restRemainingSeconds(execution);return `<div class="m26-session-timers" aria-live="polite"><span><small>Tiempo activo</small><strong data-session-elapsed>${e(elapsed)}</strong></span><span><small>Descanso</small><strong data-session-rest>${rest?`${rest} s`:'—'}</strong></span></div>`;}
export function renderSessionBuilder({draft,catalog,query='',filters={},actionState}={}){
  const results=catalog.search(query,filters).slice(0,24);
  const blocks=(draft.blocks||[]).map((b,i)=>{if(b.type==='exercise')return `<article class="m26-builder-block" data-block-id="${e(b.id)}"><span>${i+1}</span><div><strong>${e(b.name)}</strong><small>${e(b.sets)} series · ${e(b.reps)} · ${e(b.restSeconds)} s</small></div><button type="button" data-session-action="remove-block" data-block-id="${e(b.id)}">Eliminar</button></article>`;return `<article class="m26-builder-block" data-block-id="${e(b.id)}"><span>${i+1}</span><div><strong>${e(groupName(b.type))}</strong><small>${e((b.exerciseIds||[]).length)} ejercicios · ${e(b.rounds)} rondas</small></div><button type="button" data-session-action="remove-block" data-block-id="${e(b.id)}">Eliminar</button></article>`;}).join('')||'<p class="m26-empty-copy">Añade ejercicios desde la biblioteca.</p>';
  const cards=results.map(x=>`<button type="button" class="m26-exercise-result" data-session-action="add-exercise" data-exercise-id="${e(x.id)}"><strong>${e(x.name_es)}</strong><span>${e(x.pattern)} · ${e(x.equipment)}</span></button>`).join('')||'<p class="m26-empty-copy">No hay coincidencias.</p>';
  return `<section class="m26-session-builder"><header><div><p class="m26-eyebrow">Constructor</p><h2>${e(draft.title)}</h2></div><div class="m26-inline-actions"><button type="button" data-session-action="exit-session">Salir</button><button type="button" class="m26-primary-action" data-session-action="publish">Revisar y publicar</button></div></header>${actionState?`<div class="m26-action-state is-${e(actionState.status)}" role="status">${e(actionState.message)}</div>`:''}<div class="m26-builder-grid"><div class="m26-panel"><label>Buscar ejercicio<input type="search" value="${e(query)}" data-session-search autocomplete="off"></label><div class="m26-exercise-results">${cards}</div></div><div class="m26-panel"><div class="m26-builder-toolbar"><button type="button" data-session-action="add-group" data-group-type="biserie">Biserie</button><button type="button" data-session-action="add-group" data-group-type="triserie">Triserie</button><button type="button" data-session-action="add-group" data-group-type="circuito">Circuito</button><button type="button" data-session-action="add-group" data-group-type="amrap">AMRAP</button><button type="button" data-session-action="add-group" data-group-type="tabata">Tabata</button>${draft.activeGroupId?`<button type="button" data-session-action="close-group">Cerrar grupo activo</button>`:``}</div>${draft.activeGroupId?`<p class="m26-notice">Selecciona ejercicios para completar el grupo activo.</p>`:``}<div class="m26-builder-blocks">${blocks}</div></div></div></section>`;
}
export function renderGuidedExecution({execution,session,catalog,actionState}={}){
  const state=actionState&&actionState.status!=='idle'?`<div class="m26-action-state is-${e(actionState.status)}" role="${actionState.status==='error'||actionState.status==='retry'?'alert':'status'}" aria-live="polite">${e(actionState.message|| (actionState.status==='loading'?'Procesando…':''))}</div>`:'';
  const sync=syncBanner(execution);
  if(execution.status==='ready')return `<section class="m26-guided">${state}${sync}<div class="m26-panel m26-empty"><h2>${e(session.title||'Sesión IBERFIT')}</h2><p>Todo listo para comenzar.</p><div class="m26-inline-actions"><button type="button" data-session-action="exit-session">Volver</button><button type="button" class="m26-primary-action" data-session-action="start">Iniciar sesión</button></div></div></section>`;
  if(execution.status==='awaiting_feedback')return `<section class="m26-guided">${state}${sync}${timerStrip(execution)}<div class="m26-panel"><p class="m26-eyebrow">Cierre de sesión</p><h2>Cuéntanos cómo te fue</h2><div class="m26-field-grid"><label>RPE de la sesión<input type="number" min="1" max="10" data-session-feedback-rpe></label><label>Comentario<textarea data-session-feedback-comment></textarea></label><label><input type="checkbox" data-session-feedback-pain> Tuve dolor o molestia</label><label>Detalle de dolor<textarea data-session-feedback-pain-notes></textarea></label></div><button type="button" class="m26-primary-action" data-session-action="finish">Finalizar y guardar</button></div></section>`;
  if(execution.status==='paused')return `<section class="m26-guided">${state}${sync}${timerStrip(execution)}<div class="m26-panel m26-empty"><p class="m26-eyebrow">Sesión en pausa</p><h2>${e(session.title||'Sesión IBERFIT')}</h2><p>Tu progreso está conservado. Reanuda cuando estés listo.</p><button type="button" class="m26-primary-action" data-session-action="resume">Reanudar sesión</button><label>Motivo para cancelar<input data-session-cancel-reason></label><button type="button" data-session-action="cancel">Cancelar sesión</button></div></section>`;
  if(execution.status==='cancelled')return `<section class="m26-guided">${state}${sync}<div class="m26-panel m26-empty"><h2>Sesión cancelada</h2><p>${e(execution.cancellationReason||'La sesión fue cancelada.')}</p><p>${execution.syncStatus==='clean'?'Cancelación confirmada.':'Cancelación guardada localmente; aún no está confirmada.'}</p><button type="button" class="m26-primary-action" data-session-action="exit-session">Volver a sesiones</button></div></section>`;
  if(execution.status==='completed')return `<section class="m26-guided">${state}${sync}<div class="m26-panel m26-empty"><h2>Sesión completada</h2><p>${execution.syncStatus==='clean'?'Los resultados quedaron confirmados.':'Los resultados están guardados en este dispositivo y pendientes de sincronización.'}</p><button type="button" class="m26-primary-action" data-session-action="exit-session">Volver a sesiones</button></div></section>`;
  const step=currentStep(execution,session);if(!step)return '<section class="m26-panel"><h2>Sesión finalizada</h2></section>';
  const ex=catalog.get(step.exerciseId)||step.exercise||{};const progress=Math.round(((execution.index+(execution.setIndex/Math.max(1,step.totalSets)))/execution.queue.length)*100);const alternatives=catalog.search('',{pattern:ex.pattern}).filter(x=>x.id!==step.exerciseId).slice(0,8).map(x=>`<option value="${e(x.id)}">${e(x.name_es)}</option>`).join('');
  return `<section class="m26-guided">${state}${sync}<header><div><p class="m26-eyebrow">Sesión guiada</p><h2>${e(ex.name_es||ex.name||step.exerciseId)}</h2><p>Serie ${step.setNumber} de ${step.totalSets}</p></div><strong>${progress}%</strong></header>${timerStrip(execution)}<div class="m26-progress" aria-label="Progreso ${progress}%"><span style="width:${progress}%"></span></div><div class="m26-guided-main"><article class="m26-panel"><h3>Indicaciones</h3><p>${e((ex.cues||[]).join(' · ')||'Mantén una técnica estable y controla el rango.')}</p><div class="m26-field-grid"><label>Repeticiones<input type="number" min="0" data-set-field="reps"></label><label>Tiempo (s)<input type="number" min="0" data-set-field="seconds"></label><label>Carga<input type="text" data-set-field="load"></label><label>RPE<input type="number" min="1" max="10" data-set-field="rpe"></label><label>RIR<input type="number" min="0" max="10" data-set-field="rir"></label><label>Notas<textarea data-set-field="notes"></textarea></label></div><button type="button" class="m26-primary-action" data-session-action="complete-set">Completar serie</button></article><aside class="m26-panel m26-panel-soft"><button type="button" data-session-action="previous">Anterior</button><button type="button" data-session-action="next">Siguiente</button><button type="button" data-session-action="rest-minus">−15 s</button><button type="button" data-session-action="rest-plus">+15 s</button><label>Alternativa<select data-session-substitute>${alternatives}</select></label><label>Motivo<input data-session-substitute-reason></label><button type="button" data-session-action="substitute" data-from-exercise-id="${e(step.exerciseId)}">Usar alternativa</button><button type="button" data-session-action="pause">Pausar sesión</button><label>Motivo para cancelar<input data-session-cancel-reason></label><button type="button" data-session-action="cancel">Cancelar sesión</button></aside></div></section>`;
}
